// Host-facing HTTP implementation of ImageGenApi. Firebase-free: auth + base URL
// come from the injected BackendHttpDeps, so any host (PlaygroundHost, Telegram/Steam
// shells) can construct it. Do NOT import from barrel exports (imageGen/index.ts).

import { ImageGenApi, ImageGenParams, ImageGenResult, ImageGenJobEvent, DepthEstimationParams, DepthEstimationResult, RemoveBackgroundParams, RemoveBackgroundResult, UpscaleImageParams, UpscaleImageResult } from './ImageGenApi';
import { assertValidImageGenSeed } from './validateSeed';
import { resolveGameSessionToken } from '../http/backendHttpDeps';
import type { BackendHttpDeps } from '../http/backendHttpDeps';

export class HttpImageGenApi implements ImageGenApi {
  private readonly appId: string;
  private readonly deps: BackendHttpDeps;

  constructor(appId: string, deps: BackendHttpDeps) {
    this.appId = appId;
    this.deps = deps;
  }

  private async authedPost<T>(path: string, body: Record<string, unknown>): Promise<T> {
    const idToken = await this.deps.getIdToken();
    const baseUrl = this.deps.getCloudRunUrl();
    const url = `${baseUrl}/v1/imagegen/${this.appId}/${path}`;
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${idToken}`,
      'x-consumer': 'sdk',
    };

    const gst = await resolveGameSessionToken(this.deps.getGameSessionToken);
    if (gst) headers['x-h5-game-session'] = gst;

    const response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      const errorText = await response.text();
      let errorMessage = `Request failed (${response.status})`;
      try {
        const errorJson = JSON.parse(errorText);
        errorMessage = errorJson.error || errorJson.message || errorMessage;
      } catch {
        if (errorText) errorMessage = errorText;
      }
      throw new Error(errorMessage);
    }

    return response.json();
  }

  async generate(params: ImageGenParams): Promise<ImageGenResult> {
    assertValidImageGenSeed(params.seed);
    return this.authedPost<ImageGenResult>('generate', params as unknown as Record<string, unknown>);
  }

  async estimateDepth(params: DepthEstimationParams): Promise<DepthEstimationResult> {
    return this.authedPost<DepthEstimationResult>('estimate-depth', params as unknown as Record<string, unknown>);
  }

  async removeBackground(params: RemoveBackgroundParams): Promise<RemoveBackgroundResult> {
    return this.authedPost<RemoveBackgroundResult>('remove-background', params as unknown as Record<string, unknown>);
  }

  async upscaleImage(params: UpscaleImageParams): Promise<UpscaleImageResult> {
    return this.authedPost<UpscaleImageResult>('upscale-image', params as unknown as Record<string, unknown>);
  }

  async getCompletedJobs(): Promise<ImageGenJobEvent[]> {
    return [];
  }
}
